// th18_s7_b8 — TH18 v1.00a Extra, stage07 BossCard4 (spell 90).
// source_ref: st07bs.ecl.txt:1587-1638 (BossCard4), 1640-1692 (BossCard4_at).
// Shell: validation.md independent control, no body collision; real enemy keeps
// the source circular body 48 / hurt 40 (= target radii 24 / 20) and is invincible.

const TIME_LIMIT: int = 4980;      // 120 opening buffer + 4800 source slot-0 timeout + 60 tail
const OPENING_BUFFER: int = 120;

const TH18_SHARD: int = 512;       // etSprite(1, 10, 1): source type 10, color 1
const BOSS_ENTRY_Y: fx = 128fx;    // Boss(): movePos(0, 128); SPELL_ID==95 branch not taken
const FIRST_SHOT: int = 90;        // BossCard4 "+90" time label

// 0x20000 MOVE, b=9 (quad in-out) + 0x4 ACCEL, followed by the source 0x80000000 WAIT.
// MOVE target is fixed in the caller at effect entry; the position curve starts and
// ends at rest, so two opposite constant accelerations reproduce it.  The source
// stores each position difference as velocity, so the restored entry speed keeps the
// chord direction (atan2 of the acceleration pair).
xformdef MOVE9(ax: fx, ay: fx, half: int, rest: int, s0: fx, q: angle, w: int) {
    set_speed(0fx);
    set_gravity(ax, ay);
    wait(half);
    set_gravity(at_effect(0fx - ax), at_effect(0fx - ay));
    wait(rest);
    set_angle(at_effect(atan2(ay, ax)));
    set_speed(s0);
    set_gravity(at_effect(0.01fx * cos(q)), at_effect(0.01fx * sin(q)));
    wait(120);
    set_gravity(0fx, 0fx);
    wait(w);
}

async sub card_boss() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);

    // BossCard4: movePosTime(60, 0, 0.0f, 64.0f); then the +90 time label.
    move_to(60, 0fx, 64fx, EASE_LINEAR);
    wait(FIRST_SHOT);

    // BossCard4_at local state.  %B and %C are this helper's own locals; the main
    // task's same-named locals are never shared.
    var bx: fx = 0fx;      // %B
    var cy: fx = 440fx;    // %C
    var wt: int = 900;     // $D, WAIT record rewritten once per outer group

    for outer in 0..20000 {
        // Source setInterrupt(0, 0, 4800, "Boss5"): stop the attack at the timeout
        // instead of continuing the next card.
        if $self_age >= 4800 { break; }

        bx = 0fx;   // _468: %B = _f(0) at the start of every outer group
        // 0x80000000 WAIT is configured at _468, before the 16 inner waves, so all
        // bullets of one outer group share this value; $D drops by 4 per inner wave.
        var wtime: int = wt;
        if wtime < 0 { wtime = 0; }   // source a<1 advances immediately

        for inner in 0..16 {
            // setInterrupt(0,0,4800,...) also cuts an outer group mid-way.
            if $self_age >= 4800 { break; }
            // etSpeed(1, %RANDF*0.4f, 0.0f): one draw shared by the 8 bullets.
            var s0: fx = (((rand(65536) - 32768) as fx) / 65536 + 0.5fx) * 0.4fx;

            // Positive-x half: etExSet index 1 MOVE, then etOffsetAbs.
            var dur1: int = 200 + rand(60);                                  // a = 200+$RAND%60
            var xt1: fx = bx + (((rand(65536) - 32768) as fx) / 32768) * 32fx; // r = %B+RANDF2*32
            var sx1: fx = bx + (((rand(65536) - 32768) as fx) / 32768) * 16fx; // offsetAbs x = %B+RANDF2*16
            var sy: fx = -4fx * s0;        // ANIM entry: position -= 4*velocity (velocity = s0 down)
            var ax1: fx = (4fx * (xt1 - sx1)) / dur1 / dur1;
            var ay1: fx = (4fx * (cy - sy)) / dur1 / dur1;
            var half1: int = dur1 / 2;
            var rest1: int = dur1 - half1;
            for i1 in 0..4 {
                // 0x4 ACCEL: s = pi/2 + RANDF2*pi/3, drawn per bullet before etOn.
                var q1: angle = 90deg + (((((rand(65536) - 32768) as fx) / 32768) * 10923fx) as int) as angle;
                _ = fire(TH18_SHARD, 1, sx1, sy, s0, 90deg,
                         MOVE9(ax1, ay1, half1, rest1, s0, q1, wtime), none);
            }

            // Negative-x half: second MOVE/offset configuration, four more bullets.
            var dur2: int = 200 + rand(60);
            var xt2: fx = -bx + (((rand(65536) - 32768) as fx) / 32768) * 32fx;
            var sx2: fx = -bx + (((rand(65536) - 32768) as fx) / 32768) * 16fx;
            var ax2: fx = (4fx * (xt2 - sx2)) / dur2 / dur2;
            var ay2: fx = (4fx * (cy - sy)) / dur2 / dur2;
            var half2: int = dur2 / 2;
            var rest2: int = dur2 - half2;
            for i2 in 0..4 {
                var q2: angle = 90deg + (((((rand(65536) - 32768) as fx) / 32768) * 10923fx) as int) as angle;
                _ = fire(TH18_SHARD, 1, sx2, sy, s0, 90deg,
                         MOVE9(ax2, ay2, half2, rest2, s0, q2, wtime), none);
            }

            bx = bx + 12fx;
            wait(4);
            wt = wt - 4;
        }
        if cy > 180fx { cy = cy - 18fx; }
    }
    loop { wait(60); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, BOSS_ENTRY_Y, 1000, 0, 0, 0, card_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
